/* Support macros for code generated by tools/lotus/recomp.py. */
#ifndef RECOMP_RT_H
#define RECOMP_RT_H

#include "arm26.h"
#include "machine.h"

typedef void (*recomp_chunk_fn)(arm26_t *cpu);
extern const arm26_region_t recomp_regions[];
extern const unsigned recomp_region_count;

void hybrid_install(void);
void hybrid_run(arm26_t *cpu);
extern unsigned long long hybrid_fallback_steps;

#define LOCALS \
    uint32_t r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14; \
    uint32_t fN, fZ, fC, fV; int32_t cyc; int io_seen = 1; uint8_t *const ram = M.ram

#define SYNC_IN() do { \
    r0 = cpu->r[0]; r1 = cpu->r[1]; r2 = cpu->r[2]; r3 = cpu->r[3]; r4 = cpu->r[4]; \
    r5 = cpu->r[5]; r6 = cpu->r[6]; r7 = cpu->r[7]; r8 = cpu->r[8]; r9 = cpu->r[9]; \
    r10 = cpu->r[10]; r11 = cpu->r[11]; r12 = cpu->r[12]; r13 = cpu->r[13]; r14 = cpu->r[14]; \
    fN = cpu->psr >> 31; fZ = (cpu->psr >> 30) & 1; fC = (cpu->psr >> 29) & 1; fV = (cpu->psr >> 28) & 1; \
    cyc = cpu->cycles; } while (0)

#define PSR() ((cpu->psr & 0x0C000003u) | (fN << 31) | (fZ << 30) | (fC << 29) | (fV << 28))

#define SYNC_OUT() do { \
    cpu->r[0] = r0; cpu->r[1] = r1; cpu->r[2] = r2; cpu->r[3] = r3; cpu->r[4] = r4; \
    cpu->r[5] = r5; cpu->r[6] = r6; cpu->r[7] = r7; cpu->r[8] = r8; cpu->r[9] = r9; \
    cpu->r[10] = r10; cpu->r[11] = r11; cpu->r[12] = r12; cpu->r[13] = r13; cpu->r[14] = r14; \
    cpu->psr = PSR(); cpu->cycles = cyc; } while (0)

#define RD32(dst, a) do { uint32_t _a = (a) & 0x03FFFFFCu; \
    if (_a < GUEST_RAM_SIZE) (dst) = *(const uint32_t *)(ram + _a); else { io_seen = 1; (dst) = bus_read32(_a); } } while (0)

#define RD32R(dst, a) do { uint32_t _e = (a), _w; RD32(_w, _e); \
    if (_e & 3) { unsigned _s = (_e & 3) * 8; _w = (_w >> _s) | (_w << (32 - _s)); } (dst) = _w; } while (0)

#define RD8(dst, a) do { uint32_t _a = (a) & 0x03FFFFFFu; \
    if (_a < GUEST_RAM_SIZE) (dst) = ram[_a]; else { io_seen = 1; (dst) = bus_read8(_a); } } while (0)

/* IOC writes may end the slice (arm26_yield), so cycles round-trip on the slow path. */
#define WR32(a, v) do { uint32_t _a = (a) & 0x03FFFFFCu, _v = (v); \
    if (_a < GUEST_RAM_SIZE) *(uint32_t *)(ram + _a) = _v; \
    else { cpu->cycles = cyc; bus_write32(_a, _v); cyc = cpu->cycles; } } while (0)

#define WR8(a, v) do { uint32_t _a = (a) & 0x03FFFFFFu, _v = (v); \
    if (_a < GUEST_RAM_SIZE) ram[_a] = (uint8_t)_v; \
    else { cpu->cycles = cyc; bus_write8(_a, _v); cyc = cpu->cycles; } } while (0)

/* Closing branch of a wait loop (see idle_loop in recomp.py). One pass has just run
   from the loop head without touching hardware, so every further pass is the same until
   an interrupt: take all the passes that fit in the slice at once. The interpreter
   arrives at the same cycle count one pass at a time. */
#define IDLE(cost) do { if (!io_seen && cyc > 0) cyc -= ((cyc + (cost) - 1) / (cost)) * (cost); } while (0)

/* Execute one instruction through the interpreter (rare or mode-changing forms). */
#define INTERP(op, cur) do { \
    SYNC_OUT(); cpu->pc = ((cur) + 4) & PC_MASK; arm26_exec(cpu, (op), (cur)); SYNC_IN(); \
    if (cpu->stop) { pc = cpu->pc; goto leave; } \
    if (cpu->pc != (((cur) + 4) & PC_MASK)) { pc = cpu->pc; goto dispatch; } } while (0)

/* Register-specified shift, identical to the interpreter. */
static inline uint32_t shift_reg(unsigned type, uint32_t b, uint32_t amt, uint32_t *carry)
{
    if (!amt) return b;
    switch (type) {
    case 0:
        if (amt < 32) { *carry = (b >> (32 - amt)) & 1; return b << amt; }
        *carry = (amt == 32) ? (b & 1) : 0; return 0;
    case 1:
        if (amt < 32) { *carry = (b >> (amt - 1)) & 1; return b >> amt; }
        *carry = (amt == 32) ? (b >> 31) : 0; return 0;
    case 2:
        if (amt < 32) { *carry = (b >> (amt - 1)) & 1; return (uint32_t)((int32_t)b >> amt); }
        *carry = b >> 31; return (uint32_t)((int32_t)b >> 31);
    default:
        amt &= 31;
        if (amt) b = (b >> amt) | (b << (32 - amt));
        *carry = b >> 31; return b;
    }
}

#endif
